import{z as p,x as B,o as t,c as F,q as n,j as l,D as r,d as e,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"期货交易所匹配算法","description":"","frontmatter":{"title":"期货交易所匹配算法","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/futures-matching-algo.md","filePath":"quant/futures-matching-algo.md","lastUpdated":1791063341000}'),A={name:"quant/futures-matching-algo.md"};function d(u,a,c,m,D,h){const o=B("Mermaid");return t(),F("div",null,[a[2]||(a[2]=n('<h1 id="期货交易所匹配算法" tabindex="-1">期货交易所匹配算法 <a class="header-anchor" href="#期货交易所匹配算法" aria-label="Permalink to &quot;期货交易所匹配算法&quot;">​</a></h1><div class="epigraph"><p>股票微观结构直觉多半来自价格–时间优先。期货撮合常常是 FIFO、pro-rata、分配给指定做市商的配额，以及它们的分层组合。同一宏观信息，扫簿形态可以完全不同。</p><footer>—— 据 Harris, Trading and Exchanges 对优先规则与期货市场的论述；对照 Cordella and Foucault, JFQA, 1999</footer></div><p><a href="/quant/closing-auction-design">收盘竞价</a>谈股票参照价。缺口是期货：指数、利率、商品的价格发现大量发生在期货领先现货的结构里，而匹配算法不是单一 FIFO。本课把<a href="/quant/price-time-pro-rata">价格–时间对 pro-rata</a>落到交易所设计：为何利率产品爱比例分配、股指期货常偏 FIFO、顶层混合如何改变做市激励。不重画 LOB 阶梯，不写某个月的参数表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>期货合约同质、tick 相对波动往往较粗，同一价位容易堆积。FIFO 下堆积变成极端占位竞赛，托管租金高。pro-rata 让大做市商用资本换份额，近端看起来极厚，真实可重复深度取决于撤余。设计者还要养活指定做市商：给他们保证分配（allocation）再对其余 FIFO 或 pro-rata。问题是算法如何服务三类用户——套保者的大单、高频做市、小投机——以及跨品种套利在不同算法之间如何踩空。</p><p><span class="marginnote">术语翻译：pro-rata 就是「按出资比例分单」——价格相同时不看谁先排队，而是看你在该价位挂了多少量，按量的占比切分成交，像股东按持股比例分红。FIFO 则是谁先到谁先得，时间的竞赛；pro-rata 是资本的竞赛。</span></p><p>闪电崩盘发生在 E-mini 上，匹配是 FIFO 为主的股指期货。不能把那条空簿路径归因于 pro-rata；但利率期货的「假厚」会给出另一条幻象。</p><h3 id="分层算法" tabindex="-1">分层算法 <a class="header-anchor" href="#分层算法" aria-label="Permalink to &quot;分层算法&quot;">​</a></h3><p>常见结构：第一层满足做市商义务配额，第二层 pro-rata，残差 FIFO；或反向。分层创造两场博弈：先成为有配额的人，再决定展示量。进入做市项目的固定成本，是 Grossman–Miller 进入的制度版。</p><p><span class="marginnote">Globex 等系统的具体名称与比例随合约而变。教学只保留分层逻辑。写进生产代码前必须读该合约当前规则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较同一信息跳下的成交分配：FIFO 把量给队头少数订单；pro-rata 把量洒到许多大单。账户层若可得，看集中度。市场质量：近端深度、撤单率、小单限价比例、有效冲击。粗 tick + pro-rata 预测：深度高、限价小单少、消息率高。细 tick + FIFO 预测：深度分散、速度竞赛更纯。</p><p><span class="marginnote">数字实例：一笔 1000 手的市价买单打进来——FIFO 下，队头两个各挂 500 手的订单全拿走，成交名单只有两家；pro-rata 下，五个各挂 2000 手的大户各按 20% 份额分得 200 手，挂 10 手的小单只分到 0.5 手。同一条 K 线背后的成交名单与信息去向完全不同。</span></p><p>与现货套利：期货算法决定谁先获得领先价格的成交。若期货 pro-rata 让许多做市商同时成交，领先信息的分配更分散；FIFO 让最快的人定义价格。信息份额会随算法变，而不只随品种。</p>',14)),(t(),l(s,null,{default:r(()=>[i(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Algo%5B%22FIFO%20%2F%20pro-rata%20%2F%20%E9%85%8D%E9%A2%9D%E5%88%86%E5%B1%82%22%5D%20--%3E%20Inc%5B%22%E5%8D%A0%E4%BD%8D%20vs%20%E5%A0%86%E9%87%8F%20vs%20%E8%BF%9B%E5%85%A5%E9%A1%B9%E7%9B%AE%22%5D%0A%20%20Inc%20--%3E%20Shape%5B%22%E8%BF%91%E7%AB%AF%E5%BD%A2%E7%8A%B6%E4%B8%8E%E5%8F%AF%E9%87%8D%E5%A4%8D%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20Shape%20--%3E%20Disc%5B%22%E5%8F%91%E7%8E%B0%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%B8%8E%E5%86%B2%E5%87%BB%E5%B9%BB%E8%A7%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"匹配算法分配瞬时租金，从而决定谁愿意在 Grossman–Miller 意义上在场。股指期货用户更杂、对「公平次序」更敏感，FIFO 更常见；利率期货做市更机构化，pro-rata 用资本换持续报价。混合试图两者都要：义务商保证在场，其余用速度或尺寸竞争。",-1)),a[5]||(a[5]=E("p",null,"对执行：在 pro-rata 上「排队到队头」不是目标，展示量与是否愿意被分配到的随机一刀才是。切片算法从股票 FIFO 复制过来会系统性错。隐藏流动性在期货上更贵（份额损失），可见堆量更极端。",-1)),(t(),l(s,null,{default:r(()=>[i(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20MO%5B%22%E5%B8%82%E4%BB%B7%E4%B9%B0%E5%8D%95%201000%20%E6%89%8B%22%5D%20--%3E%20FIFO%5B%22FIFO%20%E9%80%9A%E9%81%93%22%5D%0A%20%20MO%20--%3E%20PR%5B%22pro-rata%20%E9%80%9A%E9%81%93%22%5D%0A%20%20FIFO%20--%3E%20F1%5B%22%E6%8C%89%E6%97%B6%E9%97%B4%E5%85%88%E5%90%8E%3Cbr%2F%3E%E9%98%9F%E5%A4%B4%E5%85%88%E5%90%83%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E5%85%A8%E9%83%A8%201000%20%E6%89%8B%3Cbr%2F%3E%E5%BD%92%E5%89%8D%E5%87%A0%E4%B8%AA%E6%9C%80%E6%97%A9%E6%8C%82%E5%8D%95%22%5D%0A%20%20PR%20--%3E%20P1%5B%22%E6%8C%89%E6%8C%82%E5%87%BA%E9%87%8F%E5%8D%A0%E6%AF%94%3Cbr%2F%3E%E6%AF%94%E4%BE%8B%E5%88%86%E9%85%8D%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E5%A4%A7%E6%88%B7%E6%8C%89%E4%BB%BD%E9%A2%9D%E5%88%86%E4%B8%80%E5%88%80%3Cbr%2F%3E%E5%B0%8F%E5%8D%95%E5%8F%AA%E5%BE%97%E5%88%86%E4%BD%8D%E9%9B%B6%E5%A4%B4%22%5D%0A%20%20F2%20--%3E%20OUT%5B%22%E6%88%90%E4%BA%A4%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%B8%8D%E5%90%8C%3Cbr%2F%3E%E4%BF%A1%E6%81%AF%E4%B8%8E%E7%A7%9F%E9%87%91%E5%8E%BB%E5%90%91%E4%B8%8D%E5%90%8C%22%5D%0A%20%20P2%20--%3E%20OUT%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：初学者容易把第一档上万手的堆量当成「可以随便吃的流动性」。在 pro-rata 下，那笔巨量是许多大做市商的联合展示，你一动手，对方立刻撤余（cancel-replace 换位置），真实可成交量往往只有零头——厚度是博弈出来的，不是库存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>算法与手续费、托管、数据源打包，单改匹配可能被费用抵消。期权到期日、交割规则会临时改变用户结构，同算法不同日不可比。国债期货与商品期货的客户风险偏好不同，同样 pro-rata 结果不同。本课不评估哪一种算法「更好」，只说明它是一等设计对象。</p><p><span class="marginnote">看见第一档上万手，先问算法再问「流动性好」。这是优先规则课在期货上的重复，值得再写一次，因为发现往往从这里传到股票。</span></p><p>期权把「一笔指令」变成一篮子腿，FIFO 还是 pro-rata 都无法单独提供同时性。下一课的复杂订单簿是匹配对象的维度变化，不是再调一层分配比例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期货匹配常在 FIFO、pro-rata 与做市配额之间分层，改变占位、堆量与进入。</li><li>近端厚度在 pro-rata 下不可按 FIFO 直觉解读为可重复深度。</li><li>算法影响谁定义领先价格，从而影响现货信息份额。</li><li>出处：Harris, <em>Trading and Exchanges</em>；Cordella and Foucault, <em>JFQA</em>, 1999；排队与比例见本站优先规则课。</li></ul>',7))])}const O=p(A,[["render",d]]);export{I as __pageData,O as default};
